/* AP United States Government and Politics, Unit 4: American Political Ideologies and Beliefs. Original teaching and practice
   aligned to the topics of the College Board's AP U.S. Government and Politics Course and Exam Description as best recalled:
   4.1 American Attitudes About Government and Politics, 4.2 Political Socialization, 4.3 Changes in Ideology, 4.4 Influence of
   Political Events on Ideology, 4.5 Measuring Public Opinion, 4.6 Evaluating Public Opinion Data, 4.7 Ideologies of Political
   Parties, 4.8 Ideology and Policymaking, 4.9 Ideology and Economic Policy, 4.10 Ideology and Social Policy.
   The unit is strictly non-partisan: liberal, conservative and libertarian positions are described in the neutral textbook terms
   of the framework ("generally", "more likely to") and no party, ideology, politician or policy is endorsed or disparaged. No
   current officeholder or current poll number is named. Every poll, sample, crosstab and tax figure is fictional and labelled
   so. Margin of error uses the classroom approximation 1/sqrt(n) (as a proportion; times 100 for percentage points), which is
   close to the 95 percent margin for a proportion near one half. A lead is called too close to call when it is within the
   margin and a clear lead only when it is more than twice the margin. The pictures are drawn in code. */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const board=(title,lines)=>({t:'board',title,lines});
const table=(title,head,col,rows)=>({t:'setups',title,head,cols:[col],rows});
const flow=(title,labels,details)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((label,i)=>{const x=i*36;for(const [j,xy] of [[0,[x,15]],[1,[x+28,15]],[2,[x+28,27]],[3,[x,27]]])pts['ABCD'[j]+i]=xy;polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[x+14,7],text:details[i]});if(i<labels.length-1){pts['P'+i]=[x+29,21];pts['Q'+i]=[x+35,21];segs.push({v:`P${i}Q${i}`,arrows:1,col:i});}});return {t:'figure',title,view:[-3,103,0,34],pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join('')};};
/* a scaled timeline: the x axis is calendar years and labels alternate above and below the line */
const years=(title,span,events)=>{const pts={A:[span[0]+4,0],B:[span[1]-4,0]},notes=[];events.forEach(([y,text],i)=>{pts['E'+i]=[y,0];notes.push({at:[y,i%2?-4.5:4.5],text});});return {t:'figure',title,view:[span[0],span[1],-9,9],pts,hide:Object.keys(pts).join(''),dots:events.map((e,i)=>'E'+i).join(''),segs:[{v:'AB',arrows:1}],notes};};
/* labelled boxes in a row or grid: schematic only */
const regions=(title,boxes)=>{const pts={},polys=[],notes=[];boxes.forEach(([label,x0,y0,x1,y1,detail],i)=>{[[x0,y0],[x1,y0],[x1,y1],[x0,y1]].forEach((xy,j)=>{pts['ABCD'[j]+i]=xy;});polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[(x0+x1)/2,y0+2.4],text:detail});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes,dots:'',hide:Object.keys(pts).join('')};};
const bars=(title,list,suffix)=>({t:'chart',kind:'bars',title,suffix,bars:list.map(([label,value])=>({label,value}))});
const beliefs=table('Core American political beliefs','Belief','Meaning',[['Popular sovereignty','Government gets its authority from the people'],['Individualism','Personal freedom and responsibility'],['Equality of opportunity','A fair chance, not equal results'],['Rule of law','Officials obey the law too'],['Limited government','Power restricted by the Constitution']]);
const agents=flow('Political socialization',['Family','School and peers','Media and events'],['first teacher','civics and friends','news and crises']);
const spectrum=regions('The usual one-dimensional spectrum: schematic',[['Liberal',2,8,32,26,'active government'],['Moderate',36,8,64,26,'mixed views'],['Conservative',68,8,98,26,'limited government']]);
const eventYears=years('Events that shaped opinion (years to scale)',[1920,2025],[[1929,'1929: Crash'],[1941,'1941: Pearl Harbor'],[1974,'1974: Nixon resigns'],[2001,'2001: Sept. 11'],[2008,'2008: Financial crisis']]);
const rally=bars('Fictional presidential approval around a crisis',[['Before',48],['After',63]],'%');
const pollYears=years('Two famous polling misses (years to scale)',[1925,1960],[[1936,'1936: Literary Digest'],[1948,'1948: Truman upset']]);
const lead=bars('Fictional poll, 225 adults, margin about 6.7 points',[['Candidate A',48],['Candidate B',44]],'%');
const interval=(title,lo,hi,mid)=>({t:'chart',kind:'numline',title,axis:[lo-4,hi+4],rows:[{label:`${mid}±${hi-mid}`,span:{from:lo,to:hi,closedFrom:true,closedTo:true}}]});
const ranges=interval('A fictional poll estimate with its margin of error',44,50,47);
const families=table('Four labels in textbook terms','Label','Typical emphasis',[['Liberal','Active government role to promote equality'],['Conservative','Limited economic role; traditional values'],['Libertarian','Limited government in economy and personal life'],['Moderate','Mixed positions between the poles']]);
const taxes=bars('Fictional tax on a 30,000 dollar income',[['Flat 15%',4500],['Progressive',5000]],'');
const proposal=bars('Fictional Proposal R: share in favor',[['Group M',60],['Group N',40],['All',55]],'%');
